import { ArrowUpRightIcon } from "lucide-react";
import Link from "next/link";

import reference from "@/lib/content/schema-reference.generated.json";
import { POLICY_HREF } from "@/lib/content/verification";
import { REPO_URL } from "@/lib/url";
import { cn } from "@/lib/utils";

interface FieldEntry {
  key: string;
  type: string;
  required: boolean | string;
  description: string | null;
  values: string[] | null;
}

type Field = FieldEntry & {
  appliesTo: "both" | "alum" | "contributor";
  items: FieldEntry[] | null;
};

// SAFETY: generated by scripts/generate-content.mjs (schemaReference) in exactly this shape.
const fields = reference.fields as Field[];

// Lists longer than this collapse behind a "show values" toggle.
const INLINE_VALUES = 8;

const APPLIES_TO_LABEL = { alum: "Alumni", both: null, contributor: "Contributors" } as const;

const Values = ({ values }: { values: string[] }) => {
  const chips = (
    <span className="flex flex-wrap gap-1">
      {values.map((value) => (
        <code className="rounded bg-black/5 px-1.5 py-0.5 font-mono text-[11px]" key={value}>
          {value}
        </code>
      ))}
    </span>
  );
  if (values.length <= INLINE_VALUES) {
    return chips;
  }
  return (
    <details className="group">
      <summary className="text-muted-foreground hover:text-foreground cursor-pointer text-xs">
        {values.length} allowed values
      </summary>
      <div className="pt-1.5">{chips}</div>
    </details>
  );
};

const Badge = ({ children, tone }: { children: string; tone: "required" | "muted" }) => (
  <span
    className={cn(
      "rounded-full px-1.5 py-px text-[10px] font-semibold tracking-wide uppercase",
      tone === "required" ? "bg-secondary text-secondary-foreground" : "bg-black/6 text-[#4A433D]"
    )}
  >
    {children}
  </span>
);

const FieldRow = ({ field }: { field: Field }) => {
  const appliesTo = APPLIES_TO_LABEL[field.appliesTo];
  return (
    <li className="flex flex-col gap-1.5 border-black/7 py-3 not-last:border-b">
      <div className="flex flex-wrap items-center gap-1.5">
        <code className="font-mono text-[13px] font-semibold">{field.key}</code>
        <span className="text-muted-foreground text-xs">{field.type}</span>
        {field.required === true && <Badge tone="required">Required</Badge>}
        {field.required === "contributors" && (
          <Badge tone="required">Required for contributors</Badge>
        )}
        {appliesTo && <Badge tone="muted">{`${appliesTo} only`}</Badge>}
      </div>
      {field.description && <p className="text-muted-foreground text-xs">{field.description}</p>}
      {field.values && <Values values={field.values} />}
      {field.items && (
        <ul className="mt-0.5 flex flex-col gap-2 border-l border-black/10 pl-3">
          {field.items.map((item) => (
            <li className="flex flex-col gap-1" key={item.key}>
              <div className="flex flex-wrap items-center gap-1.5">
                <code className="font-mono text-xs font-semibold">{item.key}</code>
                <span className="text-muted-foreground text-[11px]">{item.type}</span>
                {item.required && <Badge tone="required">Required</Badge>}
              </div>
              {item.description && (
                <p className="text-muted-foreground text-[11px]">{item.description}</p>
              )}
              {item.values && <Values values={item.values} />}
            </li>
          ))}
        </ul>
      )}
    </li>
  );
};

/**
 * Every field a submission may include, from profile.schema.json and the tag
 * vocabulary, shown beside the YAML editor.
 */
export const SchemaReference = () => (
  <section
    aria-labelledby="schema-reference-title"
    className="rounded-lg border border-black/10 bg-white/55 px-4 pt-3 pb-1"
  >
    <div className="flex flex-wrap items-baseline justify-between gap-2">
      <h2 className="text-sm font-semibold" id="schema-reference-title">
        Fields you can include
      </h2>
      <Link
        className="text-muted-foreground hover:text-foreground inline-flex items-center gap-1 text-xs"
        href={`${REPO_URL}/blob/develop/profile.schema.json`}
        target="_blank"
      >
        Full schema
        <ArrowUpRightIcon className="size-3" />
      </Link>
    </div>
    <ul>
      {fields.map((field) => (
        <FieldRow field={field} key={field.key} />
      ))}
    </ul>
    <p className="text-muted-foreground border-t border-black/7 py-3 text-xs">
      Maintainers fill in the rest ({reference.maintainerOnly.join(", ")}). See the{" "}
      <Link className="underline" href={POLICY_HREF}>
        editorial policy
      </Link>{" "}
      for what counts as a source.
    </p>
  </section>
);
